const std=@import("std");const M=@import("experimental/soil_physiology_core.zig");const Old=@import("experimental/hydration_continuous_core.zig");const K=@import("experimental/soil_root_kernel_v2.zig");const B=@import("experimental/scalar_water.zig");
const Fixture=struct{cell:M.Cell,surface:f64,vapor:f64};
fn fixture()!std.json.Parsed(Fixture){return std.json.parseFromSlice(Fixture,std.testing.allocator,@embedFile("experimental/soil_physiology_fixture.json"),.{});}
fn pools(c:M.Cell,surface:f64,soil:f64,vapor:f64)K.State{var s=K.State{.surface=surface,.soil=soil,.vapor=vapor};for(c.cohorts,0..)|co,i|s.cohorts[i]=.{.biomass=co.biomass,.support=co.support_mass,.root_fraction=co.root_fraction,.storage_fraction=co.retention_allocation,.water=co.stored_water};return s;}
fn water(s:K.State,held:f64)f64{var x=s.surface+s.soil+s.vapor+held;for(s.cohorts)|co|x+=co.water;return x;}
fn carbon(c:M.Cell)f64{var x:f64=c.detritus;for(c.cohorts)|co|x+=co.biomass;return x;}
fn nitrogen(c:M.Cell)f64{var x:f64=c.nutrient;for(c.cohorts)|co|x+=@as(f64,co.biomass)*M.nutrient_per_carbon;return x;}
fn oldCell(c:M.Cell)!Old.Cell{const j=try std.json.stringifyAlloc(std.testing.allocator,c,.{});defer std.testing.allocator.free(j);const p=try std.json.parseFromSlice(Old.Cell,std.testing.allocator,j,.{.ignore_unknown_fields=true});defer p.deinit();return p.value;}
test "soil gates root zero exact core and RNG parity"{const f=try fixture();defer f.deinit();for([_]f32{0,0.000001,0.000175,0.001})|depth|{var a=f.value.cell;var b=try oldCell(a);for(0..30)|_|{const ea=M.Environment{.temperature=300,.depth_km=depth,.light=1,.carbon_available=1,.oxygen_carbon_capacity=1};const eb=Old.Environment{.temperature=300,.depth_km=depth,.light=1,.carbon_available=1,.oxygen_carbon_capacity=1};const af=M.step(&a,ea,720);const bf=Old.step(&b,eb,720);try std.testing.expectEqualDeep(b,try oldCell(a));try std.testing.expectEqualDeep(bf,Old.Flux{.fixed=af.fixed,.recycled=af.recycled,.failed_patches=af.failed_patches,.grazed=af.grazed,.grazing_respired=af.grazing_respired});}}}
test "soil gates paid zero canopy and unchanged total upkeep"{const f=try fixture();defer f.deinit();var c=f.value.cell.cohorts[1];const before=c;c.root_fraction=1;try std.testing.expectEqual(@as(f32,0),M.producerHeightMeters(c));try std.testing.expectEqual(M.ProducerForm.mat,M.producerForm(c));try std.testing.expectEqual(@as(f32,0),M.filmProtection(c));try std.testing.expectEqual(M.frondMass(before),M.frondMass(c));try std.testing.expectEqual(M.supportMaintenancePerDay(before),M.supportMaintenancePerDay(c));}
fn run(root:f32,conductance:f64,regime:u8,dt:f32)!void{
 const f=try fixture();defer f.deinit();var cell=f.value.cell;cell.cohorts[1].root_fraction=root;
 var state=pools(cell,f.value.surface,0,f.value.vapor);const w0=water(state,0);
 const setup=K.step(state,.{.dt=21600,.capacity=1,.infiltration_rate=1.0/86400.0}).?;state=setup.state;try std.testing.expectApproxEqAbs(w0,water(state,0),1e-9);
 var recharge_paid:f64=0;var held:f64=0;if(regime!=0){held=state.surface;state.surface=0;}
 var co2:f64=1;var oxygen:f64=1;const c0=carbon(cell)+co2;const n0=nitrogen(cell);var maxw:f64=0;var maxc:f64=0;var maxn:f64=0;var rootflow=[_]f64{0,0,0,0};var requests=[_]f64{0,0,0,0};var storeflow=[_]f64{0,0,0,0};var fixed:f64=0;var recycled:f64=0;var grazed:f64=0;var zero_receipts:u64=0;var extinction:?usize=null;
 const perday:usize=@intFromFloat(86400/dt);
 for(0..7*perday)|tick|{
 if(regime==2 and tick>0 and tick%(2*perday)==0){const t=B.transfer(held,state.surface,0.25);std.debug.print("RECHARGE_EVENT root={d} k={d} dt={d} day={d} source={d} target={d} requested=0.25 paid={d} accepted={} quantum={d}\n",.{root,conductance,dt,tick/perday,held,state.surface,t.paid,t.accepted,t.quantum});held=t.source;state.surface=t.target;recharge_paid+=t.paid;}
 state=pools(cell,state.surface,state.soil,state.vapor);var demand=[_]f64{0,0,0,0};var exposure=[_]f64{0,0,0,0};var heights=[_]f64{0,0,0,0};const start_depth=state.surface/1000;
 for(cell.cohorts,0..)|c,i|{heights[i]=M.producerHeightMeters(c);exposure[i]=if(heights[i]>0)std.math.clamp((heights[i]-start_depth)/heights[i],0,1) else if(start_depth==0)1 else 0;demand[i]=0.1*@as(f64,M.frondMass(c))*dt/86400*exposure[i];}
 const r=K.step(state,.{.dt=dt,.capacity=1,.infiltration_rate=1.0/86400.0,.evaporation_rate=0.02/86400.0,.drainage_rate=0.01/86400.0,.conductance=conductance/86400,.demand=demand,.exposure=exposure,.depth_m=start_depth}).?;state=r.state;var h=[_]f32{0,0,0,0};for(0..4)|i|{h[i]=@floatCast(r.h_paid[i]);cell.cohorts[i].stored_water=state.cohorts[i].water;rootflow[i]+=r.root_receipts[i];storeflow[i]+=r.store_receipts[i];requests[i]+=demand[i];if(demand[i]>0 and r.h_paid[i]==0)zero_receipts+=1;}
 const flux=M.step(&cell,.{.temperature=300,.depth_km=@floatCast(state.surface/1000000),.light=1,.carbon_available=@floatCast(co2),.oxygen_carbon_capacity=@floatCast(oxygen),.qa_hydration=h},dt);
 try std.testing.expect(cell.liquid_return==0 and cell.vapor_return==0); // Root-only: no storage or hidden escrow consumption.
 co2+=@as(f64,flux.recycled)-flux.fixed;oxygen+=@as(f64,flux.fixed)-flux.recycled;fixed+=flux.fixed;recycled+=flux.recycled;grazed+=flux.grazed;try std.testing.expect(co2>=0 and oxygen>=0);
 maxw=@max(maxw,@abs(water(state,held)-w0));maxc=@max(maxc,@abs(carbon(cell)+co2-c0));maxn=@max(maxn,@abs(nitrogen(cell)-n0));try std.testing.expect(maxw<=1e-9 and maxc<=1e-4 and maxn<=1e-4);if(extinction==null and cell.cohorts[1].biomass==0)extinction=tick+1;
 if((tick+1)%perday==0){const line=try std.json.stringifyAlloc(std.testing.allocator,.{.root=root,.conductance_per_day=conductance,.regime=regime,.dt=dt,.day=(tick+1)/perday,.cell=cell,.surface=state.surface,.soil=state.soil,.vapor=state.vapor,.held=held,.recharge_paid=recharge_paid,.setup_infiltrated=setup.infiltrated,.root_receipts=rootflow,.storage_receipts=storeflow,.demand=requests,.last_h=r.h_paid,.last_height=heights,.last_exposure=exposure,.zero_receipts=zero_receipts,.fixed=fixed,.recycled=recycled,.grazed=grazed,.co2=co2,.oxygen=oxygen,.water_residual=maxw,.carbon_residual=maxc,.nitrogen_residual=maxn,.extinction_tick=extinction},.{});defer std.testing.allocator.free(line);std.debug.print("SOIL_PHYSIOLOGY {s}\n",.{line});}
 }
}
test "soil matrix fixed36 seven day cases"{for([_]f32{0,0.25})|r|for([_]f64{1,10})|k|for(0..3)|regime|for([_]f32{1440,720,360})|dt|try run(r,k,@intCast(regime),dt);}

test "soil gates invalid root atomic refusal"{const f=try fixture();defer f.deinit();for([_]f32{-0.1,1.1,std.math.nan(f32),std.math.inf(f32)})|bad|{var c=f.value.cell;c.cohorts[1].root_fraction=bad;const before=c;try std.testing.expect(!M.validCell(c,1000));const flux=M.step(&c,.{.temperature=300,.depth_km=0,.light=1,.carbon_available=1,.oxygen_carbon_capacity=1},1440);try std.testing.expectEqualSlices(u8,std.mem.asBytes(&before),std.mem.asBytes(&c));try std.testing.expectEqualDeep(M.Flux{},flux);}var c=f.value.cell;c.cohorts[1].root_fraction=0.75;c.cohorts[1].retention_allocation=0.5;const before=c;try std.testing.expect(!M.validCell(c,1000));_=M.step(&c,.{.temperature=300,.depth_km=0,.light=1,.carbon_available=1,.oxygen_carbon_capacity=1},1440);try std.testing.expectEqualDeep(before,c);}
